insert into public.fact_checks (claim, classification, explanation, red_flags, how_to_verify, source_title, source_url, source_type, source_date) values
  ('O WhatsApp vai começar a cobrar uma mensalidade para continuar sendo usado', 'provavelmente_falsa', 'Esse é um boato recorrente que circula há anos em correntes de mensagem. O WhatsApp nunca cobrou, e não há indício de cobrança para o uso pessoal do aplicativo.', ARRAY['Mensagem em cadeia pedindo repasse imediato', 'Sem fonte oficial citada', 'Reaparece periodicamente com pequenas variações']::text[], ARRAY['Consulte o site oficial do WhatsApp (whatsapp.com)', 'Verifique a seção de ajuda do próprio aplicativo', 'Procure agências de fact-checking brasileiras (Aos Fatos, Lupa, Comprova, Boatos.org)']::text[], 'Padrão de boato recorrente, amplamente documentado por agências brasileiras de fact-checking (ex.: Aos Fatos, Lupa, Comprova, Boatos.org, e-Farsas) ao longo dos anos', NULL, 'fact_checking', 'Recorrente'),
  ('Roupas ou panfletos com anestesia são deixados em portas de casas para facilitar sequestro relâmpago', 'provavelmente_falsa', 'Não existe caso comprovado desse método. É um boato de segurança recorrente, já desmentido diversas vezes por corporações policiais e agências de checagem.', ARRAY['Apelo emocional de medo', 'Pede compartilhamento imediato "para proteger a família"', 'Nunca cita uma ocorrência policial verificável específica']::text[], ARRAY['Consulte o site da Polícia Civil ou Militar do seu estado', 'Procure agências de fact-checking brasileiras']::text[], 'Padrão de boato recorrente, amplamente documentado por agências brasileiras de fact-checking (ex.: Aos Fatos, Lupa, Comprova, Boatos.org, e-Farsas) ao longo dos anos', NULL, 'fact_checking', 'Recorrente'),
  ('Botijões de gás de uma marca específica vão explodir e famílias devem verificar imediatamente', 'provavelmente_falsa', 'Alertas desse tipo circulam recorrentemente citando supostos "engenheiros da empresa", sem qualquer comunicado oficial real da fabricante ou de órgãos reguladores.', ARRAY['Cita um "engenheiro" ou "funcionário" não identificável', 'Pede repasse urgente', 'Nenhum comunicado oficial da empresa citada']::text[], ARRAY['Consulte diretamente o site oficial da fabricante do botijão', 'Consulte a ANP (Agência Nacional do Petróleo, Gás Natural e Biocombustíveis)']::text[], 'Padrão de boato recorrente, amplamente documentado por agências brasileiras de fact-checking (ex.: Aos Fatos, Lupa, Comprova, Boatos.org, e-Farsas) ao longo dos anos', NULL, 'fact_checking', 'Recorrente'),
  ('Vacinas contêm microchip ou tecnologia 5G para controle ou rastreamento da população', 'provavelmente_falsa', 'Não existe base técnica nem evidência que sustente essa alegação. É uma das desinformações mais desmentidas por agências de fact-checking e órgãos de saúde no mundo todo.', ARRAY['Alegação tecnicamente implausível (tamanho de agulha x componentes eletrônicos)', 'Sem fonte científica verificável', 'Linguagem conspiratória']::text[], ARRAY['Consulte o site do Ministério da Saúde (gov.br/saude) ou da Anvisa', 'Procure agências de fact-checking brasileiras e internacionais']::text[], 'Padrão de boato recorrente, amplamente documentado por agências brasileiras de fact-checking (ex.: Aos Fatos, Lupa, Comprova, Boatos.org, e-Farsas) ao longo dos anos', NULL, 'fact_checking', 'Recorrente'),
  ('Sua conta do WhatsApp será excluída se você não repassar esta mensagem para um número mínimo de contatos', 'provavelmente_falsa', 'O WhatsApp nunca exclui contas por falta de repasse de mensagens. Esse é um formato clássico de corrente projetada para se espalhar rapidamente.', ARRAY['Prazo ou número mínimo de repasses especificado', 'Ameaça de perda da conta', 'Formato típico de corrente']::text[], ARRAY['Consulte a central de ajuda oficial do WhatsApp (faq.whatsapp.com)']::text[], 'Padrão de boato recorrente, amplamente documentado por agências brasileiras de fact-checking (ex.: Aos Fatos, Lupa, Comprova, Boatos.org, e-Farsas) ao longo dos anos', NULL, 'fact_checking', 'Recorrente'),
  ('Uma cédula de dinheiro em circulação vai perder validade em breve sem comunicado oficial', 'provavelmente_falsa', 'Mudanças na validade de cédulas no Brasil são sempre anunciadas oficialmente, com prazo longo, pelo Banco Central — nunca por corrente de mensagem.', ARRAY['Prazo curto e alarmista', 'Nenhuma fonte do Banco Central citada', 'Pede repasse urgente']::text[], ARRAY['Consulte o site oficial do Banco Central do Brasil (bcb.gov.br)']::text[], 'Padrão de boato recorrente, amplamente documentado por agências brasileiras de fact-checking (ex.: Aos Fatos, Lupa, Comprova, Boatos.org, e-Farsas) ao longo dos anos', NULL, 'fact_checking', 'Recorrente'),
  ('Produtos alimentícios estariam sendo intencionalmente contaminados em supermercados, segundo mensagem em cadeia', 'nao_confirmada', 'Alegações desse tipo circulam periodicamente sem nunca apontar um caso, local ou data verificável. Sem uma fonte oficial (Anvisa, vigilância sanitária, boletim de ocorrência), não é possível confirmar nem descartar por completo — mas o padrão é característico de boato.', ARRAY['Nenhum local, data ou produto específico verificável', 'Apelo emocional envolvendo crianças ou famílias', 'Pede compartilhamento amplo e imediato']::text[], ARRAY['Consulte o site da Anvisa (gov.br/anvisa) para alertas sanitários oficiais', 'Procure a vigilância sanitária do seu estado ou município']::text[], 'Padrão de boato recorrente, amplamente documentado por agências brasileiras de fact-checking (ex.: Aos Fatos, Lupa, Comprova, Boatos.org, e-Farsas) ao longo dos anos', NULL, 'fact_checking', 'Recorrente'),
  ('Um novo vírus apaga todos os contatos e fotos do celular se uma determinada imagem ou link for aberto', 'nao_confirmada', 'Existem golpes reais de malware distribuídos por links e arquivos, mas alertas em corrente com essa descrição genérica raramente correspondem a uma ameaça real específica — geralmente são boatos ou versões distorcidas de alertas de segurança legítimos.', ARRAY['Descrição vaga, sem nome do malware ou fonte técnica', 'Pede repasse em massa', 'Instrui a não abrir "qualquer" arquivo sem especificar qual']::text[], ARRAY['Consulte o CERT.br (cert.br), o centro de resposta a incidentes de segurança do Brasil', 'Mantenha o sistema operacional e antivírus atualizados']::text[], 'Padrão de boato recorrente, amplamente documentado por agências brasileiras de fact-checking (ex.: Aos Fatos, Lupa, Comprova, Boatos.org, e-Farsas) ao longo dos anos', NULL, 'fact_checking', 'Recorrente'),
  ('Ligar de volta para um número desconhecido específico gera uma cobrança altíssima automática', 'nao_confirmada', 'Golpes de "toque e desliga" (que induzem a vítima a ligar de volta para números com tarifação especial) existem, mas alegações genéricas sobre um número específico circulando em corrente raramente podem ser confirmadas sem uma fonte da operadora ou da Anatel.', ARRAY['Número específico citado sem fonte oficial', 'Valor de cobrança exagerado e sem comprovação', 'Formato de corrente']::text[], ARRAY['Consulte o site da Anatel (gov.br/anatel)', 'Não ligue de volta para números desconhecidos e verifique com sua operadora']::text[], 'Padrão de boato recorrente, amplamente documentado por agências brasileiras de fact-checking (ex.: Aos Fatos, Lupa, Comprova, Boatos.org, e-Farsas) ao longo dos anos', NULL, 'fact_checking', 'Recorrente'),
  ('Uma foto ou vídeo de um desastre ou evento antigo está sendo compartilhado como se fosse de um acontecimento atual', 'enganosa_fora_de_contexto', 'Esse é um padrão comum de desinformação: conteúdo real, mas reaproveitado fora do contexto original de data e local. Cada caso precisa ser verificado individualmente comparando a imagem com sua origem.', ARRAY['Imagem sem data ou fonte original citada', 'Legenda alarmista associando a um evento recente específico', 'Qualidade ou marca d''água inconsistente com a suposta origem']::text[], ARRAY['Use uma busca reversa de imagens (ex.: Google Imagens) para encontrar a publicação original', 'Procure a mesma imagem em veículos jornalísticos estabelecidos com data de publicação']::text[], 'Padrão de boato recorrente, amplamente documentado por agências brasileiras de fact-checking (ex.: Aos Fatos, Lupa, Comprova, Boatos.org, e-Farsas) ao longo dos anos', NULL, 'fact_checking', 'Recorrente');
